static void *opt6_first(uint8_t *opt, uint8_t *end)
{
  /* make sure we have option number and length. */
  if ((uint8_t *)opt6_ptr(opt, 0) > end)
    return NULL;
  /* make sure we have bytes promised by length. */
  if ((uint8_t *)opt6_ptr(opt, opt6_len(opt)) > end)
    return NULL;
  return opt;
